class Solution {
public:
    string minWindow(string s1, string s2) {
        int m = s1.size(), n = s2.size();
        int i = 0, minLen = INT_MAX, start = -1;

        while (i < m) {
            int j = 0;
            while (i < m && j < n) {
                if (s1[i] == s2[j]) j++;
                i++;
            }
            if (j < n) break;

            int end = i;
            j = n - 1;
            i--;
            while (j >= 0) {
                if (s1[i] == s2[j]) j--;
                i--;
            }
            i++;

            if (end - i < minLen) {
                minLen = end - i;
                start = i;
            }
            i++;
        }
        return start == -1 ? "" : s1.substr(start, minLen);
    }
};

class Solution {
    public String minWindow(String s1, String s2) {
        int m = s1.length(), n = s2.length();
        int i = 0, minLen = Integer.MAX_VALUE, start = -1;

        while (i < m) {
            int j = 0;
            while (i < m && j < n) {
                if (s1.charAt(i) == s2.charAt(j)) j++;
                i++;
            }
            if (j < n) break;

            int end = i;
            j = n - 1;
            i--;
            while (j >= 0) {
                if (s1.charAt(i) == s2.charAt(j)) j--;
                i--;
            }
            i++;

            if (end - i < minLen) {
                minLen = end - i;
                start = i;
            }
            i++;
        }
        return start == -1 ? "" : s1.substring(start, start + minLen);
    }
}

